# Generated by build.py from recipe.yml for recipe http-rotate-a-password-without-downtime. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'single' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'single/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'token.txt'), "control-token-0123456789abcdefghij`n")
[IO.File]::WriteAllText((Join-Path $PWD 'app-v2.json'), "{`"user`":`"app-v2`",`"password`":`"new-secret`"}")
[IO.File]::WriteAllText((Join-Path $PWD 'app-changed.json'), "{`"user`":`"app`",`"password`":`"new-secret`"}")
[IO.File]::WriteAllText((Join-Path $PWD 'app-password.json'), "{`"password`":`"new-secret`"}")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--user', 'app-v1:old-secret', '--control', 'http://127.0.0.1:8082', '--control-token-file', 'token.txt', 'https://127.0.0.1:8080/', 'ftp://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -s -o NUL -w "%{scheme} %{response_code}\n" --json @app-v2.json -H "Authorization: Bearer control-token-0123456789abcdefghij" http://127.0.0.1:8082/v1/accounts --next -s -o NUL -w "%{scheme} %{response_code}\n" --cacert server.pem -u app-v2:new-secret https://127.0.0.1:8080/hello.txt --next -s -o NUL -w "%{scheme} %{response_code}\n" --ssl-reqd --cacert server.pem -u app-v1:old-secret ftp://127.0.0.1:8081/hello.txt } finally { Stop-Process $server0 }
